/* Vanilla JavaScript multi-page presentation frontend. All data is synthetic and local to the browser. */
(function(){
'use strict';
const ROOT=document.getElementById('app');
const PAGE=document.body.dataset.page || 'welcome';
const RAW_AREA=document.body.dataset.area || 'public';
const BASE=document.body.dataset.base || '';
let db=DemoData.load();
const AREA=RAW_AREA==='shared' ? (db.user.portal || 'college') : RAW_AREA;
if(AREA==='officer'&&db.user.portal!=='officer'){db.user={...db.user,portal:'officer',role:'verification',name:'Verification Officer (Demo)'};DemoData.save(db)}
if(AREA==='college'&&db.user.portal!=='college'){db.user={...db.user,portal:'college',role:'college-admin',name:'College Administrator (Demo)'};DemoData.save(db)}
const APP_STAGES=['Submitted','Secure intake','OCR & extraction','Rule checks','Source & anomaly review','Compliance assistance','Officer scrutiny','Competent authority decision'];
const COLLEGE_NAV=[['Dashboard','dashboard','home'],['Applications','applications','file'],['New application','new-application','plus'],['Documents','documents','folder'],['Validation results','validation','search'],['Corrections','corrections','alert'],['Tracking','tracking','flow'],['Notifications','notifications','bell']];
const OFFICER_NAV=[['Dashboard','dashboard','home'],['Applications','applications','file'],['Document workbench','workbench','search'],['Anomaly flags','anomalies','alert'],['Source verification','source-verification','check'],['Compliance review','compliance','shield'],['Infrastructure evidence','infrastructure','folder'],['Department workflow','workflow','flow'],['Review tasks','tasks','list'],['Final decisions','decisions','stamp'],['Reports','reports','chart'],['Audit trail','audit','clock'],['Rule configuration','rules','settings'],['User roles','users','users'],['Security design','security','lock']];
const ICONS={home:'<path d="m3 10 9-7 9 7v11H3z"/><path d="M9 21v-7h6v7"/>',file:'<path d="M5 2h9l5 5v15H5z"/><path d="M14 2v6h5M8 13h8M8 17h8"/>',plus:'<path d="M12 4v16M4 12h16"/>',folder:'<path d="M3 6h7l2 3h9v11H3z"/>',search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',alert:'<path d="M12 3 2 21h20zM12 9v5M12 17h.01"/>',flow:'<rect x="3" y="3" width="7" height="6" rx="1"/><rect x="14" y="15" width="7" height="6" rx="1"/><path d="M10 6h4v12"/>',bell:'<path d="M6 17V9a6 6 0 0 1 12 0v8l2 2H4zM10 22h4"/>',check:'<circle cx="12" cy="12" r="9"/><path d="m7 12 3 3 7-7"/>',shield:'<path d="M12 2 3 6v6c0 6 4 9 9 10 5-1 9-4 9-10V6z"/><path d="m8 12 3 3 5-6"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01"/>',stamp:'<path d="M7 14h10v5H7zM9 14V7a3 3 0 0 1 6 0v7M5 21h14"/>',chart:'<path d="M3 3v18h18M7 17v-5M12 17V8M17 17v-9"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6M17 14a5 5 0 0 1 4 5"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M7 10V7a5 5 0 0 1 10 0v3"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.file}</svg>`}
const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const date=()=>new Date().toISOString().slice(0,10);
const now=()=>new Date().toLocaleString('en-IN',{hour12:false});
function url(section,page){return BASE+ (section==='public'?'':section+'/') +(page==='welcome'?'index.html':page+'.html')}
function link(section,page,txt,cls=''){return `<a href="${url(section,page)}" class="${cls}">${txt}</a>`}
function firstApp(){return visibleApps()[0]||db.applications[0]}
function visibleApps(){return AREA==='college'?db.applications.filter(a=>a.institutionId===db.user.institutionId):db.applications}
function getApp(id){return (AREA==='college'?visibleApps():db.applications).find(a=>a.id===id)||firstApp()}
function qapp(){return getApp(new URLSearchParams(location.search).get('app'))}
function getDoc(id){return db.documents.find(d=>d.id===id)}
function inst(id){return db.institutions.find(i=>i.id===id)?.name||'Unknown institution'}
function sClass(s){return /passed|verified|completed|recorded|resolved|submitted|reviewed|accepted/i.test(s)?'good':/correction|missing|expired|mismatch|open|rejected|failed/i.test(s)?'bad':/pending|flag|source unavailable|manual|review|required|scrutiny/i.test(s)?'warn':'neutral'}
function badge(s){return `<span class="status ${sClass(s)}">${esc(s)}</span>`}
function audit(action,appId,detail){db.audit.unshift({id:'AU-'+Date.now(),when:now(),actor:db.user.role+' (demo)',action,applicationId:appId||'—',detail:detail||''});db.audit=db.audit.slice(0,120)}
function note(applicationId,message,institutionId){let a=getApp(applicationId);db.notifications.unshift({id:'N-'+Date.now(),institutionId:institutionId||a?.institutionId||'IN-001',applicationId,message,read:false,date:date()})}
function persist(){DemoData.save(db)}
function toast(msg){let box=document.getElementById('toasts');if(!box){box=document.createElement('div');box.id='toasts';box.className='toastbox';document.body.appendChild(box)}let d=document.createElement('div');d.className='toast';d.textContent=msg;box.appendChild(d);setTimeout(()=>d.remove(),4500)}
function nav(){const nav=AREA==='college'?COLLEGE_NAV:OFFICER_NAV;return `<aside class="side" id="side"><div class="logo"><span class="mark">TS</span> ThinkSync01</div><div class="side-caption">AICTE decision-support prototype</div><div class="nav-label">${AREA==='college'?'Institution views':'AI scrutiny module'}</div>${nav.map(([name,id,ic])=>link(AREA,id,icon(ic)+`<span>${name}</span>`, 'nav-link '+(PAGE===id?'active':''))).join('')}<div class="nav-label">Account</div>${link('shared','profile',icon('users')+' My profile','nav-link')}${link('public','welcome',icon('home')+' Portal selection','nav-link')}<div class="side-foot">Independent SIH concept<br>For synthetic demonstration only.<br>Not an official AICTE service.</div></aside>`}
function top(){const names={'college-admin':'College Administrator','document-officer':'Document Officer',scrutiny:'Scrutiny Officer',verification:'Verification Officer',department:'Department Reviewer',authority:'Competent Authority',auditor:'Auditor',admin:'Module Administrator'};let choices=AREA==='college'?[['college-admin','College Administrator'],['document-officer','Document Officer']]:[['scrutiny','Scrutiny Officer'],['verification','Verification Officer'],['department','Department Reviewer'],['authority','Competent Authority'],['auditor','Auditor'],['admin','Administrator']];return `<header class="top"><div class="flex"><button class="btn nav-mobile" type="button" data-action="mobile-menu" aria-label="Toggle menu">Menu</button><span class="crumb">${AREA==='college'?'Institution':'AICTE integration concept'} / ${esc(PAGE.replaceAll('-',' '))}</span></div><div class="top-actions"><span class="banner-label">Synthetic data</span><span class="role-label small muted">Demo role</span><select aria-label="Select demo role" data-action="role" style="width:175px;min-height:31px;padding:5px">${choices.map(c=>`<option value="${c[0]}" ${db.user.role===c[0]?'selected':''}>${c[1]}</option>`).join('')}</select><span class="avatar">${esc((names[db.user.role]||'D').slice(0,1))}</span></div></header>`}
function layout(body){ROOT.innerHTML=`<div class="shell">${nav()}<div class="work">${top()}${body}<div class="footer-note">ThinkSync01 • SIH 2026 • Mock frontend only. No official AICTE integration, security enforcement, OCR or source verification is performed.</div></div></div>`}
function heading(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="btnrow">${actions}</div>`:''}</div>`}
function card(title,content,extra=''){return `<section class="card"><div class="card-header"><h2>${title}</h2>${extra}</div>${content}</section>`}
function table(head,rows){return `<div class="table-wrap"><table class="table"><thead><tr>${head.map(t=>`<th>${esc(t)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${head.length}" class="empty">No records for this view.</td></tr>`}</tbody></table></div>`}
function progress(app){let value=Math.min(100,Math.round(100*app.completed/app.total));return `<div class="flex" style="min-width:140px;gap:8px"><div class="progress" style="flex:1"><b style="width:${value}%"></b></div><span class="small">${value}%</span></div>`}
function appLink(app,section=AREA){return link(section,'application-detail',esc(app.id),'pill-link')+`<span class="small muted" style="display:block">${esc(app.category)}</span>`}
function appRows(apps,section=AREA){return apps.map(a=>[appLink(a,section),esc(inst(a.institutionId)),esc(a.stage),badge(a.status),progress(a),link(section,'application-detail','View','btn small').replace('application-detail.html','application-detail.html?app='+encodeURIComponent(a.id))])}
function appTable(apps,section=AREA){return table(['Application','Institution','Current stage','Status','Progress','Action'],appRows(apps,section))}
function stat(label,value,sub=''){return `<div class="card stat"><div class="label">${label}</div><div class="value">${value}</div><div class="hint">${sub}</div></div>`}
function filterApps(){const input=document.querySelector('#search-app');const term=(input?.value||'').toLowerCase();document.querySelectorAll('[data-search-row]').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(term)})}
function appSelect(selected){return `<select name="appId" aria-label="Select application">${visibleApps().map(a=>`<option value="${esc(a.id)}" ${a.id===selected?'selected':''}>${esc(a.id)} · ${esc(inst(a.institutionId))}</option>`).join('')}</select>`}
function selectionNotice(){return `<div class="notice">Demo-only frontend: extracted values, verification responses and rule outcomes are synthetic. Real integration requires AICTE-approved interfaces and server-enforced security.</div>`}
function commonTabs(app){let sec=AREA==='college'?'college':'officer';return `<div class="tabs">${[['application-detail','Overview'],['documents','Documents'],['validation','Checks'],['tracking','Workflow']].filter(([p])=>sec==='college'||p!=='tracking').map(([p,name])=>`<a href="${url(sec,p)}?app=${encodeURIComponent(app.id)}" class="${PAGE===p?'active':''}">${name}</a>`).join('')}</div>`}
function welcome(){ROOT.innerHTML=`<div class="landing"><div class="landing-head"><strong style="font-size:19px;color:var(--navy)">ThinkSync01 <span class="muted" style="font-weight:400">/ AICTE integration prototype</span></strong><span class="chip">Smart India Hackathon 2026</span></div><div class="landing-hero"><span class="eyebrow">Application intelligence layer</span><h1>Application validation, document authentication and compliance assistance.</h1><p>Proposed AI-assisted scrutiny module for authorized AICTE application workflows. The existing portal remains the system of record; officers retain all statutory decision-making.</p><div class="flex"><span class="chip">Document OCR</span><span class="chip">Evidence-linked findings</span><span class="chip">Official-source verification workflow</span><span class="chip">Human review</span></div></div><div class="grid g2"> <div class="card portal-card"><div><span class="eyebrow">View 01</span><h2>Institution status view</h2><p>See validation findings, correction requests, submitted documents and application progress.</p></div>${link('public','login','Open institution demo','btn primary').replace('login.html','login.html?portal=college')}</div><div class="card portal-card"><div><span class="eyebrow">View 02</span><h2>AICTE verification workbench</h2><p>Review preliminary flags, simulated source checks, documentary evidence and officer tasks.</p></div>${link('public','login','Open officer demo','btn primary').replace('login.html','login.html?portal=officer')}</div></div><div class="grid g3"><div class="card"><h3>1. Existing AICTE application</h3><p>Application and documents are received by the existing authorized process.</p></div><div class="card"><h3>2. Proposed AI scrutiny module</h3><p>OCR, configurable rules, comparisons and evidence-linked flags support early validation.</p></div><div class="card"><h3>3. Authorized officer review</h3><p>Officials examine evidence, request corrections and record outcomes.</p></div></div><div class="notice">This independent student prototype contains synthetic data. It is not an official AICTE portal and has no live verification or government database access.</div></div>`}
function login(){let officer=new URLSearchParams(location.search).get('portal')==='officer';ROOT.innerHTML=`<div class="landing" style="max-width:610px;padding-top:75px"><div class="landing-head"><strong>ThinkSync01</strong>${link('public','welcome','Back to overview')}</div><div class="card" style="margin-top:45px;padding:30px"><span class="eyebrow">Demonstration access</span><h1 style="margin:12px 0 8px">Open ${officer?'regulatory officer':'institution'} view</h1><p>Choose a demo role. No password or real authentication is used in this local prototype.</p><form id="login-form"><div class="field"><label>Portal</label><select name="portal" id="login-portal"><option value="college" ${!officer?'selected':''}>Institution status</option><option value="officer" ${officer?'selected':''}>AICTE officer workbench</option></select></div><div class="field"><label>Demo role</label><select name="role" id="login-role"><option value="${officer?'verification':'college-admin'}">${officer?'Verification Officer':'College Administrator'}</option></select></div><div class="field" id="login-inst-group" ${officer?'hidden':''}><label>Institution</label><select name="institutionId">${db.institutions.map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select></div><button class="btn primary" type="submit">Enter demonstration</button></form></div><div class="subnote">Security note: role switching is only a visual demo. Production access requires AICTE-approved authentication, server-side RBAC, institutional isolation and audit controls.</div></div>`;setLoginRoles()}
function setLoginRoles(){let portal=document.getElementById('login-portal')?.value;if(!portal)return;let roles=portal==='officer'?[['verification','Verification Officer'],['scrutiny','Scrutiny Officer'],['department','Department Reviewer'],['authority','Competent Authority'],['auditor','Auditor'],['admin','Module Administrator']]:[['college-admin','College Administrator'],['document-officer','Document Officer']];document.getElementById('login-role').innerHTML=roles.map(([v,l])=>`<option value="${v}">${l}</option>`).join('');document.getElementById('login-inst-group').hidden=portal==='officer'}
function dashboard(){let apps=visibleApps();let flags=db.flags.filter(f=>apps.some(a=>a.id===f.applicationId)&&f.status!=='Resolved');let corrections=db.corrections.filter(c=>apps.some(a=>a.id===c.applicationId)&&c.status==='Requested');let title=AREA==='college'?'Institution validation overview':'AI scrutiny — officer overview';let stats=AREA==='college'?[
 stat('Applications',apps.length,'Institution scope'),stat('Under scrutiny',apps.filter(a=>/scrutiny|review|pending/i.test(a.status)).length,'Requires officer action'),stat('Correction requests',corrections.length,'Open institution tasks'),stat('Validation flags',flags.length,'Preliminary observations')]:[
 stat('Received applications',apps.length,'Authorized test records'),stat('Open anomaly flags',flags.length,'Not proof of misconduct'),stat('Source checks pending',db.verifications.filter(v=>/pending|unavailable|manual/i.test(v.status)).length,'Need confirmation'),stat('Decisions recorded',db.decisions.length,'By demo authority')];
let body=heading(title,AREA==='college'?'Progress of applications already submitted through the approved workflow.':'Integrated decision-support view using synthetic applications.',AREA==='college'?link('college','new-application','Create demo application','btn primary'):'')+`<div class="grid g4">${stats.join('')}</div><div class="grid g52"><div>${card('Recent applications',appTable(apps.slice(0,5)))}</div><div>${card('Items requiring attention',`<ul class="list">${(AREA==='college'?db.corrections.filter(c=>apps.some(a=>a.id===c.applicationId)):db.flags).slice(0,4).map(it=>`<li><div class="item-title">${esc(it.message||it.type||'Officer task')}</div><div class="meta">${esc(it.applicationId)} · ${esc(it.status)}${it.reason?' · '+esc(it.reason):''}</div></li>`).join('')||'<li class="muted">No open items</li>'}</ul>`)}</div></div><div class="grid g2">${card('Workflow progress',`<div class="stepper">${APP_STAGES.slice(0,4).map((v,i)=>`<div class="step ${i<2?'complete':i===2?'current':'pending'}"><span class="no">0${i+1}</span>${v}</div>`).join('')}</div><p class="subnote">Stage completion indicates process progress, not approval likelihood.</p>`)}${card('Secure integration boundary',`<div class="metric"><span>Data source</span><strong>Authorized AICTE records only</strong></div><div class="metric"><span>Verification</span><strong>Authorized issuer or manual</strong></div><div class="metric"><span>Decision</span><strong>Competent AICTE authority</strong></div><p class="subnote" style="margin-top:10px">These are proposed production safeguards; the current frontend is not connected to live systems.</p>`)}</div>`;
layout(body)}
function applications(){let apps=visibleApps();layout(heading('Applications','Search and inspect submitted application records.',AREA==='college'?link('college','new-application','New application','btn primary'):'')+card('Application register',`<div class="inline-form" style="margin-bottom:13px"><div class="field grow"><label for="search-app">Search by ID, institution or stage</label><input class="input" id="search-app" placeholder="Search applications..." data-action="search" /></div><div class="field"><label>Application status</label><select id="status-filter" data-action="status-filter"><option value="">All statuses</option>${[...new Set(apps.map(a=>a.status))].map(s=>`<option>${esc(s)}</option>`).join('')}</select></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Application</th><th>Institution</th><th>Stage</th><th>Status</th><th>Progress</th><th>Open</th></tr></thead><tbody>${apps.map(a=>`<tr data-search-row data-status="${esc(a.status)}"><td>${appLink(a)}</td><td>${esc(inst(a.institutionId))}</td><td>${esc(a.stage)}</td><td>${badge(a.status)}</td><td>${progress(a)}</td><td><a class="btn small" href="${url(AREA,'application-detail')}?app=${encodeURIComponent(a.id)}">Details</a></td></tr>`).join('')}</tbody></table></div>`))}
function newApplication(){layout(heading('Create a demonstration application','Simulate an application in the existing AICTE workflow; this is not a real submission.')+`<div class="notice warning">This page is an offline simulation to demonstrate integration. The proposed production solution would read actual applications from the authorized AICTE system.</div><form id="new-application-form">${card('Application details',`<div class="grid g2"><div class="field"><label>Institution</label><select name="institutionId" required>${db.institutions.filter(i=>i.id===db.user.institutionId).map(i=>`<option value="${i.id}">${esc(i.name)}</option>`).join('')}</select></div><div class="field"><label>Application category</label><select name="category" required><option>Extension of Approval</option><option>Programme Change</option><option>New Course Intake</option><option>Other approval-related change</option></select></div><div class="field"><label>Academic year</label><select name="year"><option>2026–27</option><option>2027–28</option></select></div><div class="field"><label>Institution reference (demo)</label><input class="input" name="reference" placeholder="e.g. REG-2026-01" maxlength="60" /></div></div><div class="field"><label>Notes</label><textarea name="notes" placeholder="Brief application note"></textarea></div><div class="form-actions"><button class="btn" type="submit" name="intent" value="draft">Save draft</button><button class="btn primary" type="submit" name="intent" value="submit">Submit in demo</button></div>` )}</form>`)}
function detail(){let a=qapp();let docs=db.documents.filter(d=>d.applicationId===a.id);let flags=db.flags.filter(f=>f.applicationId===a.id);let ver=db.verifications.filter(v=>v.applicationId===a.id);let body=heading('Application '+esc(a.id),esc(inst(a.institutionId))+' · '+esc(a.category),`<span>${badge(a.status)}</span>`)+commonTabs(a)+`<div class="grid g4">${stat('Workflow completion',Math.round(100*a.completed/a.total)+'%','Completed required stages')}${stat('Documents',docs.length,'Uploaded test files')}${stat('Open flags',flags.filter(f=>f.status!=='Resolved').length,'Evidence-linked findings')}${stat('Verification',ver.length,'Source-check records')}</div><div class="grid g52"><div>${card('Application information',`<div class="metric"><span>Academic year</span><strong>${esc(a.year)}</strong></div><div class="metric"><span>Submitted</span><strong>${esc(a.submitted||'Draft')}</strong></div><div class="metric"><span>Current stage</span><strong>${esc(a.stage)}</strong></div><div class="metric"><span>Assigned role</span><strong>${esc(a.assigned)}</strong></div><div class="metric"><span>Processing progress</span>${progress(a)}</div><p class="subnote" style="margin-top:12px">Workflow completion is not the probability of statutory approval.</p>`)}</div><div>${card('Open findings',`<ul class="list">${flags.map(f=>`<li><div class="item-title">${esc(f.type)} ${badge(f.status)}</div><div class="meta">${esc(f.reason)}</div></li>`).join('')||'<li class="muted">No current flags</li>'}</ul>`)}</div></div>${card('Document list',table(['Name','Category','Status'],docs.map(d=>[esc(d.name),esc(d.category),badge(d.status)])))}`;
layout(body)}
function documents(){let a=qapp(), docs=db.documents.filter(d=>d.applicationId===a.id);let pageSec=AREA;layout(heading('Documents','Document metadata, uploaded versions and local preview for the selected application.')+commonTabs(a)+`<div class="grid g2"><div>${card('Document register',`<div class="field"><label>Application</label>${appSelect(a.id)}</div>${table(['File','Type','Version','Status'],docs.map(d=>[esc(d.name)+`<div class="subnote">${esc(d.size)} · ${esc(d.uploaded)}</div>`,esc(d.category),'v'+d.version,badge(d.status)]))}`)}</div><div>${card('Upload evidence — local demo',`<form id="upload-form"><input type="hidden" name="applicationId" value="${esc(a.id)}" /><div class="field"><label>Document category</label><select name="category"><option>Affidavit</option><option>Certification</option><option>Permission</option><option>Land / Infrastructure</option><option>Academic Record</option><option>Faculty Record</option><option>Other Supporting Evidence</option></select></div><div class="field"><label>PDF or image</label><input class="input" type="file" name="upload" accept=".pdf,image/png,image/jpeg" required /><div class="form-help">Files are selected locally. This prototype stores metadata, not persistent file bytes.</div></div><div class="btnrow"><button class="btn primary" type="submit">Add demo record</button></div></form>`)}${card('Document handling safeguards',`<div class="metric"><span>Upload validation</span><strong>Type and size checked in browser</strong></div><div class="metric"><span>Production storage</span><strong>Protected server or object store</strong></div><div class="metric"><span>Access control</span><strong>Server-side RBAC required</strong></div><p class="subnote" style="margin-top:12px">No documents are sent to AICTE or external services.</p>`)}</div></div>`);
let sel=document.querySelector('select[name="appId"]');if(sel)sel.addEventListener('change',e=>location.href=url(pageSec,'documents')+'?app='+encodeURIComponent(e.target.value))}
function validation(){let a=qapp(), flags=db.flags.filter(f=>f.applicationId===a.id);let docs=db.documents.filter(d=>d.applicationId===a.id);let allRows=[['Document completeness',docs.length?'Passed preliminary document metadata check':'Missing documents','DEMO-COMP-01'],['Date consistency',docs.some(d=>d.status==='Expired')?'Review Required':'No issue flagged in demo','DEMO-DATE-01'],['Cross-document identifiers',flags.some(f=>f.type.includes('mismatch'))?'Mismatch detected':'No mismatch flagged in demo','DEMO-LAND-01'],['Source authentication',db.verifications.some(v=>v.applicationId===a.id&&/unavailable|manual/i.test(v.status))?'Verification pending':'Not assessed by demo','DEMO-SOURCE-01']];layout(heading('Validation results','Evidence-linked preliminary checks. These findings do not certify authenticity or compliance.')+commonTabs(a)+selectionNotice()+`<div class="grid g52"><div>${card('Configured checklist outcomes',table(['Check','Finding','Rule'],allRows.map(([t,s,r])=>[esc(t),badge(s),esc(r)])))}</div><div>${card('Evidence-linked flags',`<ul class="list">${flags.map(f=>`<li><div class="item-title">${esc(f.type)} ${badge(f.status)}</div><div class="meta">${esc(f.reason)}</div><div class="meta">Evidence: ${esc(f.evidence)}</div><div class="meta">Rule: ${esc(f.rule)}</div></li>`).join('')||'<li class="muted">No anomaly flags were generated for this demo application.</li>'}</ul>`)}</div></div>`)}
function corrections(){let apps=visibleApps();let cs=db.corrections.filter(c=>apps.some(a=>a.id===c.applicationId));layout(heading('Corrections and evidence','Track officer requests and simulate resubmitting corrected information.')+`<div class="grid g52"><div>${card('Requests',table(['Application','Request','Status','Action'],cs.map(c=>[esc(c.applicationId),esc(c.message),badge(c.status),c.status==='Requested'?`<button class="btn small" data-action="reply-correction" data-id="${esc(c.id)}">Respond</button>`:'—'])))}</div><div>${card('How correction works',`<ol><li>Officer identifies an evidence-linked issue.</li><li>Institution receives a correction request.</li><li>Institution provides revised evidence.</li><li>Officer checks the replacement and continues scrutiny.</li></ol><p class="subnote">This demo models the process but does not transfer files to AICTE.</p>`)}</div></div>`)}
function tracking(){let a=qapp();layout(heading('Application tracking','View stage completion, assignment and current blockers.')+`<div class="field" style="max-width:350px"><label>Application</label>${appSelect(a.id)}</div><div class="grid g2"><div>${card('Process stages',`<div class="stepper" style="display:grid;grid-template-columns:1fr 1fr">${APP_STAGES.map((s,i)=>`<div class="step ${i<a.completed?'complete':i===a.completed?'current':'pending'}"><span class="no">${i+1}</span>${esc(s)} <span class="small muted">${i<a.completed?'Completed':i===a.completed?'Current':'Pending'}</span></div>`).join('')}</div><p class="subnote">Selected workflow is illustrative; actual AICTE stages and dependencies must be configured.</p>`)}</div><div>${card('Status summary',`<div class="metric"><span>Status</span>${badge(a.status)}</div><div class="metric"><span>Assigned reviewer</span><strong>${esc(a.assigned)}</strong></div><div class="metric"><span>Progress</span>${progress(a)}</div><div class="metric"><span>Blocker</span><strong>${esc(a.notes||'None recorded')}</strong></div><p class="subnote" style="margin-top:15px">No promised completion time. A future estimate would use authorized historic task durations and configured service targets.</p>`)}</div></div>`);document.querySelector('select[name="appId"]')?.addEventListener('change',e=>location.href=url('college','tracking')+'?app='+encodeURIComponent(e.target.value))}
function notifications(){let ns=db.notifications.filter(n=>AREA!=='college'||n.institutionId===db.user.institutionId);layout(heading('Notifications','Requests, verification updates and progress events.',`<button class="btn" data-action="read-all">Mark all read</button>`)+card('Recent notifications',`<ul class="list">${ns.map(n=>`<li><div class="flex"><div><div class="item-title">${esc(n.message)}</div><div class="meta">${esc(n.date)} · ${esc(n.applicationId)}</div></div><div class="right btnrow">${n.read?badge('Read'):badge('Unread')}<button class="btn small" data-action="read-one" data-id="${esc(n.id)}">Mark read</button></div></div></li>`).join('')||'<li>No notifications available.</li>'}</ul>`))}
function workbench(){let a=qapp(), doc=db.documents.find(d=>d.applicationId===a.id), flag=db.flags.find(f=>f.applicationId===a.id), ver=db.verifications.find(v=>v.applicationId===a.id);let doctitle=doc?.category||'Document record';layout(heading('Document verification workbench','Review source-page evidence, extracted values, rule results and next officer actions.')+selectionNotice()+`<div class="field" style="max-width:460px"><label>Application</label>${appSelect(a.id)}</div><div class="split"><div>${card('Document preview — synthetic sample',`<div class="fake-doc"><div class="doc-sheet"><h3>${esc(doctitle)}</h3><div class="small" style="text-align:center">Illustrative uploaded document preview</div><hr>${(doc?.fields||[['Document ID','No attached sample']]).map(([k,v],i)=>`<div class="doc-label"><span>${esc(k)}</span><strong class="${/survey number/i.test(k)&&!k.startsWith('Reference')?'highlight':''}">${esc(v)}</strong></div>`).join('')}<hr><p class="small" style="font-style:italic">Demo document — no legal authenticity claim.</p></div></div><p class="subnote">Actual deployments must show the original source file, page coordinates and extraction confidence.</p>` )}</div><div>${card('Extracted fields & source check',`<div class="metric"><span>Document</span><strong>${esc(doc?.name||'Not provided')}</strong></div>${(doc?.fields||[]).map(([k,v])=>`<div class="metric"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}<div class="metric"><span>Source verification</span>${badge(ver?.status||'Not requested')}</div><div class="metric"><span>File check</span>${badge(doc?.status||'Not assessed')}</div>`)}${card('Preliminary discrepancy',flag?`<div class="notice warning"><strong>${esc(flag.type)}</strong><div class="small">${esc(flag.reason)}</div></div><div class="metric"><span>Evidence</span><strong>${esc(flag.evidence)}</strong></div><div class="metric"><span>Rule reference</span><strong>${esc(flag.rule)}</strong></div><div class="metric"><span>Review state</span>${badge(flag.status)}</div>`:'<div class="notice success">No open anomaly flag in this demo case.</div>')}${card('Officer actions',`<div class="btnrow"><button class="btn" data-action="mark-reviewed" data-id="${esc(a.id)}">Mark reviewed</button><button class="btn primary" data-action="request-correction" data-id="${esc(a.id)}">Request evidence</button><button class="btn" data-action="add-note" data-id="${esc(a.id)}">Add observation</button></div><p class="subnote" style="margin-top:10px">These actions update synthetic records and do not constitute statutory approval.</p>`)}</div></div>`);document.querySelector('select[name="appId"]')?.addEventListener('change',e=>location.href=url('officer','workbench')+'?app='+encodeURIComponent(e.target.value))}
function anomalies(){layout(heading('Potential anomaly flags','Alerts are preliminary indicators, never automatic proof of forgery or misconduct.')+card('Flagged findings',table(['Flag','Application','Category','Reason & evidence','Status','Review'],db.flags.map(f=>[esc(f.id),esc(f.applicationId),esc(f.type),`${esc(f.reason)}<div class="subnote">${esc(f.evidence)}</div>`,badge(f.status),`<a class="btn small" href="${url('officer','workbench')}?app=${encodeURIComponent(f.applicationId)}">Open case</a>`]))))}
function sourceVerification(){let a=qapp();let rows=db.verifications.map(v=>[esc(v.applicationId),esc(getDoc(v.documentId)?.name||v.documentId),esc(v.method),badge(v.status),esc(v.source),esc(v.timestamp)]);layout(heading('Source verification','Track permitted issuing-authority checks and manual follow-up.')+selectionNotice()+card('Verification register',table(['Application','Document','Method','Result','Source','Timestamp'],rows))+card('Add demo verification status',`<form id="source-form" class="inline-form"><div class="field grow"><label>Application</label>${appSelect(a.id)}</div><div class="field"><label>Outcome</label><select name="status"><option>Manual Review Required</option><option>Verification Pending</option><option>Source Unavailable</option><option>Mismatch Detected</option><option>Verified (synthetic demo only)</option></select></div><button type="submit" class="btn primary">Record simulated result</button></form><p class="subnote" style="margin-top:12px">No official issuing-authority API is used. Record 'Verified' only as a labeled synthetic scenario.</p>`))}
function compliance(){let a=qapp();let checks=[['Required document checklist','DEMO-COMP-01','Mandatory document types are present','Review Required'],['Expiry and date validation','DEMO-DATE-01','Dates checked against example rules','Check Passed'],['Cross-document consistency','DEMO-LAND-01','Survey identifier comparison','Review Required'],['Authorized source response','DEMO-SOURCE-01','External source may be unavailable','Pending Review'],['Infrastructure evidence','DEMO-INFRA-01','Submitted plans and certificates','Insufficient Evidence']];layout(heading('Regulatory checklist review','Configurable checks derived from the applicable handbook and approved instructions in production.')+selectionNotice()+`<div class="field" style="max-width:460px"><label>Application</label>${appSelect(a.id)}</div>${card('Checklist findings',table(['Test rule ID','Check','Evidence expectation','Finding'],checks.map(([name,id,desc,s])=>[esc(id),esc(name),esc(desc),badge(s)])))}`+`<div class="notice warning">The displayed rule identifiers and findings are illustrative. Confirm the current applicable AICTE Approval Process Handbook before encoding any real regulatory limits.</div>`);document.querySelector('select[name="appId"]')?.addEventListener('change',e=>location.href=url('officer','compliance')+'?app='+encodeURIComponent(e.target.value))}
function infrastructure(){let a=qapp();layout(heading('Infrastructure evidence','Review uploaded photographs, plans, certificates and potential inspection referrals.')+`<div class="grid g3">${['Building certificate','Floor plans','Laboratory photographs'].map((k,i)=>`<div class="card"><span class="eyebrow">Evidence category 0${i+1}</span><h2 style="margin:12px 0">${k}</h2><div class="doc-figure" style="height:140px;display:grid;place-items:center;color:#738396">${icon('folder')} &nbsp; Document / image preview</div><p class="small" style="margin:12px 0">${i===0?'Check completeness and submitted certificates.':i===1?'Compare available plans with documented declarations.':'Flag visible concerns for authorized officer review.'}</p>${badge(i===2?'Manual Review Required':'Evidence Pending')}</div>`).join('')}</div>${card('Infrastructure inspection rule',`<p>Computer vision or image review may flag possible issues, but cannot establish full physical compliance. Inspection decisions must be made by authorized officials.</p><p class="subnote">This is a nonfunctional evidence gallery in the offline demonstration.</p>`)}`)}
function workflow(){let a=qapp(), can= ['scrutiny','department','verification','admin'].includes(db.user.role);layout(heading('Department review workflow','Track tasks, dependencies, requests and completed scrutiny stages.')+`<div class="field" style="max-width:460px"><label>Application</label>${appSelect(a.id)}</div><div class="grid g52"><div>${card('Processing stages',`<div class="stepper" style="display:grid;grid-template-columns:1fr 1fr">${APP_STAGES.map((s,i)=>`<div class="step ${i<a.completed?'complete':i===a.completed?'current':'pending'}"><span class="no">${i+1}</span>${esc(s)} <span class="small muted">${i<a.completed?'Completed':i===a.completed?'Current':'Pending'}</span></div>`).join('')}</div>` )}</div><div>${card('Current assignment',`<div class="metric"><span>Officer role</span><strong>${esc(a.assigned)}</strong></div><div class="metric"><span>Status</span>${badge(a.status)}</div><div class="metric"><span>Progress</span>${progress(a)}</div><div class="metric"><span>Issue</span><strong>${esc(a.notes)}</strong></div><div class="form-actions"><button class="btn primary" data-action="advance-workflow" data-id="${esc(a.id)}" ${!can?'disabled':''}>Complete current stage</button><button class="btn" data-action="request-correction" data-id="${esc(a.id)}" ${!can?'disabled':''}>Request evidence</button></div><p class="subnote" style="margin-top:10px">Only relevant reviewer roles can perform these actions in demo mode. Real enforcement must be server-side.</p>`)}</div></div>`);document.querySelector('select[name="appId"]')?.addEventListener('change',e=>location.href=url('officer','workflow')+'?app='+encodeURIComponent(e.target.value))}
function tasks(){let flags=db.flags.filter(f=>f.status!=='Resolved');let corrections=db.corrections.filter(c=>c.status!=='Closed');layout(heading('Assigned review tasks','Officer queue combining flags, manual checks and correction responses.')+`<div class="grid g2">${card('Flag review queue',table(['Application','Issue','Status','Open'],flags.map(f=>[esc(f.applicationId),esc(f.type),badge(f.status),`<a href="${url('officer','workbench')}?app=${encodeURIComponent(f.applicationId)}" class="btn small">Review</a>`])))}${card('Evidence request queue',table(['Application','Request','Status'],corrections.map(c=>[esc(c.applicationId),esc(c.message),badge(c.status)])))}</div>`)}
function decisions(){let can=db.user.role==='authority';let apps=db.applications;layout(heading('Competent-authority decisions','Record a human outcome after mandatory scrutiny; automated checks never approve applications.')+`<div class="grid g52"><div>${card('Decision queue',table(['Application','Institution','Status','Progress'],apps.map(a=>[esc(a.id),esc(inst(a.institutionId)),badge(a.status),progress(a)])))}</div><div>${card('Record decision — demo role',`${can?'<div class="notice success">You are viewing the Competent Authority demo role.</div>':'<div class="notice warning">Switch the top-right demo role to Competent Authority to enable decision entry.</div>'}<form id="decision-form"><div class="field"><label>Application</label>${appSelect(apps[0]?.id)}</div><div class="field"><label>Decision</label><select name="decision" ${!can?'disabled':''}><option>Decision Recorded — Approved</option><option>Decision Recorded — Returned for Clarification</option><option>Decision Recorded — Not Approved</option></select></div><div class="field"><label>Reason / reference</label><textarea name="reason" required maxlength="500" placeholder="Mandatory reason for the official-review simulation" ${!can?'disabled':''}></textarea></div><button class="btn primary" type="submit" ${!can?'disabled':''}>Record demo decision</button></form><p class="subnote" style="margin-top:12px">An authorized AICTE authority must make all actual regulatory decisions. This frontend records only synthetic test outcomes.</p>`)}</div></div>${card('Decision history',table(['Application','Outcome','Officer','Date'],db.decisions.map(d=>[esc(d.applicationId),badge(d.outcome),esc(d.actor),esc(d.when)])))}`)}
function reports(){let count=db.applications.length;let byStatus=[...new Set(db.applications.map(a=>a.status))].map(s=>({label:s,n:db.applications.filter(a=>a.status===s).length}));let max=Math.max(1,...byStatus.map(x=>x.n));layout(heading('Reports and evaluation','Synthetic operational summaries, not measured AI accuracy or genuine processing savings.',`<button class="btn" data-action="export-apps">Export application CSV</button>`)+`<div class="grid g4">${stat('Applications',count,'Synthetic test records')}${stat('Open flags',db.flags.filter(f=>f.status!=='Resolved').length,'Preliminary review flags')}${stat('Corrections requested',db.corrections.length,'Demo workflow records')}${stat('Audit entries',db.audit.length,'Local event log')}</div><div class="grid g2">${card('Application status distribution',`<div class="chart-bars">${byStatus.map(x=>`<div class="chart-bar" title="${esc(x.label)}" style="height:${Math.round(100*x.n/max)}%"></div>`).join('')}</div><div class="chart-labels">${byStatus.map(x=>`<span>${esc(x.label)} (${x.n})</span>`).join('')}</div>`)}${card('Evaluation plan',`<ul class="list"><li><strong>OCR field accuracy</strong><div class="meta">Correct extracted fields / labelled test fields.</div></li><li><strong>Anomaly detection</strong><div class="meta">Precision, recall and false-positive rate on known test cases.</div></li><li><strong>Verification success</strong><div class="meta">Eligible authorized-source checks confirmed / eligible available checks.</div></li><li><strong>Processing effort</strong><div class="meta">Compare manual and assisted review on equivalent tasks.</div></li><li><strong>Security</strong><div class="meta">Test role isolation and unauthorized read/write prevention.</div></li></ul><p class="subnote">No fabricated performance percentages are presented.</p>`)}</div>`)}
function auditPage(){layout(heading('Audit trail','Local demonstration log of reviews, evidence changes, decisions and workflow updates.',`<button class="btn" data-action="export-audit">Export CSV</button>`)+`<div class="notice warning">This browser-based audit trail is not tamper-resistant. A real system needs protected server logging, log integrity, retention and access controls.</div>${card('Recorded events',table(['Timestamp','Actor','Action','Application','Details'],db.audit.map(a=>[esc(a.when),esc(a.actor),esc(a.action),esc(a.applicationId),esc(a.detail)])))}`)}
function rules(){
 const grid=table(['Rule ID','Category','Rule description','Version','State'],db.rules.map(r=>[esc(r.id),esc(r.category),esc(r.name),esc(r.version),badge(r.enabled?'Enabled (demo)':'Disabled')]));
 const intro=heading('Regulatory rule configuration','Illustrative rule metadata; real rule updates require authorization and version governance.');
 const governance='<p>Every real check should retain the applicable handbook or administrative instruction, effective date, rule version, evidence used, and authorized approval history. There is no rule editing in the offline prototype.</p>';
 layout(intro+selectionNotice()+card('Rule register',grid)+card('Rule governance',governance));
}
function users(){let roles=[['College Administrator','IN-001','Institution documents and responses'],['Document Officer','IN-001','Upload and correction tasks'],['Scrutiny Officer','AICTE demo','Review checklists'],['Verification Officer','AICTE demo','Manual source confirmation'],['Department Reviewer','AICTE demo','Department tasks'],['Competent Authority','AICTE demo','Final decision'],['Auditor','AICTE demo','Read-only audit']];layout(heading('Users and roles','Proposed role scopes for authorized integration.')+`<div class="notice">Role selection on this site is only a front-end demonstration. Real account permissions must be enforced by an approved identity provider and backend services.</div>${card('Example roles',table(['Role','Scope','Responsibility'],roles.map(r=>r.map(esc))))}`)}
function security(){const rows=[['Identity and access','Government-approved SSO or portal identity; MFA for privileged accounts','Backend authentication and strict RBAC'],['Institution isolation','Every record query is scoped to permitted institution and role','Server-side authorization'],['Document confidentiality','TLS, encrypted storage, malware scanning, controlled downloads','Secure backend document service'],['Source verification','Use officially authorized APIs/portals; record timestamp and source','Integration gateway and consent/authority'],['Audit and retention','Protect logs, record rule versions and officer actions','Centralized tamper-evident logging'],['AI safeguards','Evidence references, confidence, human escalation','Decision-support only']];layout(heading('Security and confidentiality','Proposed safeguards required before handling real institutional or personal information.')+`<div class="notice warning">A static HTML/CSS/JavaScript prototype cannot enforce production-grade security, securely store real documents, or access restricted AICTE databases.</div>${card('Security control map',table(['Control area','Proposed safeguard','Production enforcement'],rows.map(r=>r.map(esc))))}${card('Integration boundary',`<div class="stepper"><div class="step complete">Existing authorized AICTE portal</div><div class="step">Authenticated adapter</div><div class="step current">AI scrutiny service</div><div class="step">Evidence report</div><div class="step">Authorized officer</div></div><p class="subnote">All connections are conceptual. No actual interface or API permission is assumed.</p>`)}`)}
function profile(){layout(heading('Demo profile and session','Switching accounts only changes local prototype behavior.')+`<div class="grid g2">${card('Active demo identity',`<div class="metric"><span>Name</span><strong>${esc(db.user.name)}</strong></div><div class="metric"><span>Role</span><strong>${esc(db.user.role)}</strong></div><div class="metric"><span>Institution</span><strong>${esc(inst(db.user.institutionId))}</strong></div><div class="metric"><span>Portal</span><strong>${esc(db.user.portal)}</strong></div><div class="form-actions"><a class="btn" href="${url('public','login')}">Change demo account</a><button class="btn critical" data-action="reset">Reset synthetic data</button></div>`)}${card('Security note',`<p>There are no real credentials, official data, session tokens or document storage in this demonstration.</p><p>For deployment, integrate with an approved identity source and enforce authorization on every backend operation.</p>`)}</div>`)}
function modal(title,body){document.querySelector('.overlay')?.remove();let shell=document.createElement('div');shell.className='overlay';shell.id='dialog';shell.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="flex"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="btn small right" data-action="close-modal" aria-label="Close dialog">Close</button></div>${body}</div>`;document.body.appendChild(shell);shell.querySelector('input, textarea, select, button')?.focus()}
function closeModal(){document.getElementById('dialog')?.remove()}
function canOfficer(){return AREA==='officer'&&['verification','scrutiny','department','admin'].includes(db.user.role)}
function after(msg){persist();toast(msg);render()}
function downloadCSV(name,head,rows){function cell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}let csv=[head,...rows].map(r=>r.map(cell).join(',')).join('\r\n');let blob=new Blob(["\ufeff"+csv],{type:'text/csv;charset=utf-8;'});let href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(href),1000)}
const handlers={
 'mobile-menu':()=>document.getElementById('side')?.classList.toggle('mobile-show'),
 'close-modal':closeModal,
 'role':(el)=>{db.user.role=el.value;db.user.portal=AREA==='college'?'college':'officer';db.user.name=el.selectedOptions[0].text+' (Demo)';persist();render()},
 'search':()=>applyFilters(), 'status-filter':()=>applyFilters(),
 'read-all':()=>{db.notifications.forEach(n=>{if(AREA!=='college'||n.institutionId===db.user.institutionId)n.read=true});after('Notifications marked read')},
 'read-one':(el)=>{const n=db.notifications.find(n=>n.id===el.dataset.id);if(n)n.read=true;after('Notification marked read')},
 'reset':()=>{modal('Reset demo data',`<p>Restore the initial synthetic applications, flags, notifications and audit entries? This cannot be undone.</p><div class="btnrow"><button class="btn" data-action="close-modal">Cancel</button><button class="btn critical" data-action="reset-confirm">Reset all demo data</button></div>`)},
 'reset-confirm':()=>{db=structuredClone(DemoData.initial);after('Demo data reset')},
 'request-correction':el=>{if(!canOfficer()){toast('Select an authorized reviewer demo role first');return}let a=getApp(el.dataset.id);modal('Request additional evidence',`<form id="correction-form"><input type="hidden" name="appId" value="${esc(a.id)}"><p>Application <strong>${esc(a.id)}</strong>. The correction request will appear in the institution view.</p><div class="field"><label>Evidence request and explanation</label><textarea name="message" required minlength="10" maxlength="500" placeholder="Explain the discrepancy and the supporting evidence needed."></textarea></div><div class="btnrow"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Send demo request</button></div></form>`)},
 'reply-correction':el=>{let c=db.corrections.find(x=>x.id===el.dataset.id);if(!c)return;modal('Respond to evidence request',`<form id="correction-response"><input type="hidden" name="id" value="${esc(c.id)}"><p>${esc(c.message)}</p><div class="field"><label>Correction details</label><textarea name="reply" required minlength="8" maxlength="500" placeholder="Describe the evidence being submitted"></textarea></div><div class="field"><label>Optional replacement file name</label><input name="file" type="file" accept=".pdf,image/png,image/jpeg" class="input" /></div><div class="btnrow"><button type="button" class="btn" data-action="close-modal">Cancel</button><button class="btn primary" type="submit">Submit correction (demo)</button></div></form>`)},
 'mark-reviewed':el=>{if(!canOfficer()){toast('Reviewer demo role required');return}let a=getApp(el.dataset.id);db.flags.filter(f=>f.applicationId===a.id).forEach(f=>f.status='Reviewed');a.status='Under Scrutiny';a.stage='Officer Scrutiny';a.completed=Math.max(a.completed,5);audit('Officer review recorded',a.id,'Preliminary issue reviewed; not a statutory approval');after('Review saved as an advisory outcome')},
 'add-note':el=>{if(!canOfficer()){toast('Reviewer demo role required');return}let a=getApp(el.dataset.id);modal('Add officer observation',`<form id="observation-form"><input type="hidden" name="appId" value="${esc(a.id)}"><div class="field"><label>Observation</label><textarea name="note" required minlength="8" maxlength="500" placeholder="Record your reasoning"></textarea></div><div class="btnrow"><button type="button" class="btn" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">Save observation</button></div></form>`)},
 'advance-workflow':el=>{if(!canOfficer()){toast('Reviewer demo role required');return}let a=getApp(el.dataset.id);if(a.completed>=7){toast('Awaiting competent-authority decision');return}a.completed++;a.stage=APP_STAGES[a.completed]||'Officer scrutiny';a.status='Under Scrutiny';audit('Workflow stage completed',a.id,'Moved to '+a.stage);note(a.id,'Processing moved to '+a.stage);after('Workflow progress updated')},
 'export-apps':()=>downloadCSV('aicte-demo-applications.csv',['Application','Institution','Category','Status','Stage','Completed'],db.applications.map(a=>[a.id,inst(a.institutionId),a.category,a.status,a.stage,a.completed+'/'+a.total])),
 'export-audit':()=>downloadCSV('aicte-demo-audit.csv',['Date','Actor','Action','Application','Detail'],db.audit.map(a=>[a.when,a.actor,a.action,a.applicationId,a.detail]))
};
function applyFilters(){let term=(document.getElementById('search-app')?.value||'').toLowerCase(),status=document.getElementById('status-filter')?.value||'';document.querySelectorAll('[data-search-row]').forEach(row=>{row.hidden=!(row.textContent.toLowerCase().includes(term)&&(!status||row.dataset.status===status))})}
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el||el.matches('select,input'))return;const action=el.dataset.action;if(handlers[action]){e.preventDefault();handlers[action](el)}});
document.addEventListener('input',e=>{let el=e.target.closest('[data-action]');if(el&&el.dataset.action==='search')applyFilters()});
document.addEventListener('change',e=>{let el=e.target.closest('[data-action]');if(el&&handlers[el.dataset.action])handlers[el.dataset.action](el);if((el||e.target).id==='login-portal')setLoginRoles()});
document.addEventListener('submit',e=>{let form=e.target;if(!form.id)return;e.preventDefault();const fd=new FormData(form);
 if(form.id==='login-form'){
 let portal=fd.get('portal'),role=fd.get('role');db.user={name:portal==='college'?'Institution User (Demo)':'Review Officer (Demo)',role:String(role),portal:String(portal),institutionId:String(fd.get('institutionId')||'IN-001')};persist();location.href=url(portal, 'dashboard');return;
 }
 if(form.id==='new-application-form'){
 let intent=e.submitter?.value||'submit',id='APP-2026-'+(1000+db.applications.length+1);let a={id,institutionId:String(fd.get('institutionId')),category:String(fd.get('category')),year:String(fd.get('year')),submitted:intent==='submit'?date():'',status:intent==='submit'?'Submitted':'Draft',stage:intent==='submit'?'Submitted':'Draft',completed:intent==='submit'?1:0,total:8,fee:'Demo',assigned:'Initial scrutiny',documents:[],notes:String(fd.get('notes')||'')};db.applications.unshift(a);audit(intent==='submit'?'Demo application submitted':'Draft created',a.id,'Local synthetic record only');note(a.id,`Application ${intent==='submit'?'submitted':'saved as draft'} in demo.`,a.institutionId);persist();location.href=url('college','application-detail')+'?app='+encodeURIComponent(a.id);return;
 }
 if(form.id==='upload-form'){
 let file=fd.get('upload'),applicationId=String(fd.get('applicationId'));if(!(file instanceof File)||!file.name){toast('Choose a file');return}if(file.size>8*1024*1024){toast('Demo file limit is 8 MB');return}if(!(/\.pdf$/i.test(file.name)||/\.(png|jpe?g)$/i.test(file.name))){toast('Only PDF, PNG and JPG files are supported');return}
 let count=db.documents.filter(d=>d.applicationId===applicationId&&d.name===file.name).length,doc={id:'DOC-'+Date.now(),applicationId,name:file.name,category:String(fd.get('category')),size:(file.size/1024/1024).toFixed(2)+' MB',version:count+1,uploaded:date(),status:'Uploaded — unprocessed',fields:[]};db.documents.unshift(doc);getApp(applicationId).documents.push(doc.id);audit('Document metadata added',applicationId,`${file.name}; contents not persisted`);persist();toast('Local document metadata added; no OCR was performed');location.href=url('college','documents')+'?app='+encodeURIComponent(applicationId);return;
 }
 if(form.id==='correction-form'){
 let appId=String(fd.get('appId')),a=getApp(appId),message=String(fd.get('message')).trim();if(message.length<10)return;db.corrections.unshift({id:'COR-'+Date.now(),applicationId:appId,documentId:db.documents.find(d=>d.applicationId===appId)?.id||'',message,status:'Requested',created:date(),reply:''});a.status='Correction Required';a.stage='Awaiting institution evidence';a.notes=message;a.assigned='Institution';audit('Evidence correction requested',appId,message);note(appId,message,a.institutionId);closeModal();after('Correction request sent to institution demo');return;
 }
 if(form.id==='correction-response'){
 let c=db.corrections.find(x=>x.id===fd.get('id'));if(!c)return;c.reply=String(fd.get('reply')).trim();c.status='Resubmitted';let file=fd.get('file');if(file instanceof File&&file.name){c.reply+=' (File selected: '+file.name+'; bytes not stored)'}let a=getApp(c.applicationId);a.status='Resubmitted';a.stage='Officer re-review';a.assigned='Verification Officer';audit('Correction resubmitted',a.id,c.reply);note(a.id,'Revised evidence submitted for officer re-review',a.institutionId);closeModal();after('Correction resubmitted in local demo');return;
 }
 if(form.id==='observation-form'){
 let appId=String(fd.get('appId')),msg=String(fd.get('note')).trim();getApp(appId).notes=msg;audit('Observation recorded',appId,msg);closeModal();after('Officer note saved');return;
 }
 if(form.id==='source-form'){
 if(!['verification','scrutiny','admin'].includes(db.user.role)){toast('Select verification officer demo role');return}let appId=String(fd.get('appId')),a=getApp(appId),documentId=a.documents[0]||'',status=String(fd.get('status'));db.verifications.unshift({applicationId:appId,documentId,method:'Simulated check',status,source:'Synthetic data only',timestamp:date()});audit('Synthetic verification status recorded',appId,status);after('Mock source-verification status recorded');return;
 }
 if(form.id==='decision-form'){
 if(db.user.role!=='authority'){toast('Competent Authority demo role required');return}let appId=String(fd.get('appId')),outcome=String(fd.get('decision')),reason=String(fd.get('reason')).trim();if(reason.length<5){toast('Please provide a reason');return}let a=getApp(appId);if(outcome.includes('Approved')&&(a.completed<7||db.flags.some(f=>f.applicationId===appId&&f.status==='Open')||db.corrections.some(c=>c.applicationId===appId&&c.status==='Requested'))){toast('Resolve required scrutiny and open issues before an approval outcome');return}a.status=outcome;a.stage='Decision Recorded';a.completed=8;db.decisions.unshift({applicationId:appId,outcome,actor:'Competent Authority (demo)',reason,when:now()});audit('Competent-authority demo decision recorded',appId,reason);note(appId,`Final demo status: ${outcome}`,a.institutionId);after('Human decision recorded in synthetic demonstration');return;
 }
});
function render(){if(PAGE==='welcome'){welcome();return}if(PAGE==='login'){login();return}const funcs={dashboard,applications,'new-application':newApplication,'application-detail':detail,documents,validation,corrections,tracking,notifications,workbench,anomalies,'source-verification':sourceVerification,compliance,infrastructure,workflow,tasks,decisions,reports,audit:auditPage,rules,users,security,profile};if(funcs[PAGE])funcs[PAGE]();else layout(heading('Page not found','This local frontend page is not configured.'))}
window.addEventListener('storage',e=>{if(e.key===DemoData.KEY){db=DemoData.load();render()}});
render();
})();
